const ELEMENT_PROP_KEYS = new Set(["theme","title","subtitle","pattern","shape","hold","ambient","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  title: "Launch films, made in code",
  subtitle: "remocn · Spring release",
  pattern: "mark",
  shape: "circle",
  hold: 24,
  ambient: 24,
  accent: "#3B5BFD",
  fontFamily: "Instrument Serif",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type BokehTitleElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BokehTitleBase>;

const BokehTitleInner = forwardRef<
  HTMLDivElement,
  BokehTitleElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BokehTitle>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BokehTitleBase
          {...(componentProps as unknown as ComponentProps<typeof BokehTitleBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BokehTitle = Interactive.withSchema({
  Component: BokehTitleInner,
  componentName: "<BokehTitle>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
